from collections import Counter

def frequency_sort(s):
    count = Counter(s)
    chars = sorted(count, key=lambda ch: -count[ch])   # most frequent first
    return "".join(ch * count[ch] for ch in chars)

String frequencySort(String s) {
    Map<Character, Integer> count = new HashMap<>();
    for (char ch : s.toCharArray()) count.merge(ch, 1, Integer::sum);
    List<Character> chars = new ArrayList<>(count.keySet());
    chars.sort((a, b) -> count.get(b) - count.get(a));          // most frequent first
    StringBuilder out = new StringBuilder();
    for (char ch : chars) out.append(String.valueOf(ch).repeat(count.get(ch)));
    return out.toString();
}

string frequencySort(string s) {
