function frequencySort(s) {
  const count = new Map();
  for (const ch of s) count.set(ch, (count.get(ch) ?? 0) + 1);
  const buckets = Array.from({ length: s.length + 1 }, () => []);   // buckets[f]: characters seen f times
  for (const [ch, f] of count) buckets[f].push(ch);
  let out = "";
  for (let f = s.length; f > 0; f--) for (const ch of buckets[f]) out += ch.repeat(f);
  return out;
}

from collections import Counter

def frequency_sort(s):
    buckets = [[] for _ in range(len(s) + 1)]   # buckets[f]: characters seen f times
    for ch, f in Counter(s).items():
        buckets[f].append(ch)
    return "".join(ch * f for f in range(len(s), 0, -1) for ch in buckets[f])

String frequencySort(String s) {
    Map<Character, Integer> count = new HashMap<>();
    for (char ch : s.toCharArray()) count.merge(ch, 1, Integer::sum);
    List<List<Character>> buckets = new ArrayList<>();
    for (int f = 0; f <= s.length(); f++) buckets.add(new ArrayList<>());   // buckets[f]: characters seen f times
    for (var e : count.entrySet()) buckets.get(e.getValue()).add(e.getKey());
    StringBuilder out = new StringBuilder();
    for (int f = s.length(); f > 0; f--)
        for (char ch : buckets.get(f)) out.append(String.valueOf(ch).repeat(f));
    return out.toString();
}

string frequencySort(string s) {
    unordered_map<char, int> count;
    for (char ch : s) count[ch]++;
    vector<vector<char>> buckets(s.size() + 1);       // buckets[f]: characters seen f times
    for (auto& [ch, f] : count) buckets[f].push_back(ch);
    string out;
    for (int f = s.size(); f > 0; f--)
        for (char ch : buckets[f]) out += string(f, ch);
    return out;
}
